[21] tool exec call: const r = await tools.exec_command({
  cmd: "$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
$assetDir = (Resolve-Path -LiteralPath 'src/assets/animations').Path
$originalDir = (Resolve-Path -LiteralPath 'src/assets/animations/originals').Path
$files = Get-ChildItem -LiteralPath $assetDir -Filter '*_walk_v3_audit.png' | Sort-Object Name
foreach ($file in $files) {
  $bmp = [System.Drawing.Bitmap]::FromFile($file.FullName)
  try {
    $suspects = 0
    for ($frame=0; $frame -lt 4; $frame++) {
      $visited = New-Object 'bool[,]' 128,114
      for ($y=0; $y -lt 114; $y++) {
        for ($x=0; $x -lt 128; $x++) {
          if ($visited[$x,$y]) { continue }
          $visited[$x,$y] = $true
          $p = $bmp.GetPixel($frame*128+$x,$y)
          if ($p.A -eq 0) { continue }
          $queue = [System.Collections.Generic.Queue[object]]::new()
          $queue.Enqueue(@($x,$y))
          $count=0; $alphaSum=0; $touch=$false
          while ($queue.Count -gt 0) {
            $pt=$queue.Dequeue(); $cx=[int]$pt[0]; $cy=[int]$pt[1]
            $cp=$bmp.GetPixel($frame*128+$cx,$cy)
            $count++; $alphaSum += $cp.A
            if ($cx -eq 0 -or $cx -eq 127 -or $cy -eq 0 -or $cy -eq 113) { $touch=$true }
            foreach ($d in @(@(-1,0),@(1,0),@(0,-1),@(0,1))) {
              $nx=$cx+$d[0]; $ny=$cy+$d[1]
              if ($nx -lt 0 -or $nx -ge 128 -or $ny -lt 0 -or $ny -ge 114 -or $visited[$nx,$ny]) { continue }
              $visited[$nx,$ny]=$true
              if ($bmp.GetPixel($frame*128+$nx,$ny).A -gt 0) { $queue.Enqueue(@($nx,$ny)) }
            }
          }
          $avg=$alphaSum/[double]$count
          if ($count -lt 500 -and $touch -and $avg -lt 10) { $suspects++ }
        }
      }
    }
    $base = $file.Name -replace '_walk_v3_audit\.png$',''
    $originalPath = Join-Path $originalDir ($base + '.png')
    $combatDiff = -1
    if (Test-Path -LiteralPath $originalPath) {
      $orig=[System.Drawing.Bitmap]::FromFile($originalPath)
      try {
        $combatDiff=0
        for ($y=114; $y -lt 342; $y++) { for ($x=0; $x -lt 512; $x++) { if ($bmp.GetPixel($x,$y).ToArgb() -ne $orig.GetPixel($x,$y).ToArgb()) { $combatDiff++ } } }
      } finally { $orig.Dispose() }
    }
    Write-Output ("{0}: {1}x{2}; resíduos={3}; combatDiff={4}" -f $file.Name,$bmp.Width,$bmp.Height,$suspects,$combatDiff)
  } finally { $bmp.Dispose() }
}",
